package com.dao;import java.sql.*;import java.util.*;import com.entity.Consultation;public class ConsultationDao{private Connection c;public ConsultationDao(Connection c){this.c=c;}public boolean create(Consultation x){try(PreparedStatement p=c.prepareStatement("INSERT INTO consultations(user_id,doctor_id,requested_date,mode,reason,status) VALUES(?,?,?,?,?,'REQUESTED')")){p.setInt(1,x.userId);p.setInt(2,x.doctorId);p.setString(3,x.requestedDate);p.setString(4,x.mode);p.setString(5,x.reason);return p.executeUpdate()==1;}catch(Exception e){e.printStackTrace();return false;}}private List<Consultation> f(String q,int id){List<Consultation>a=new ArrayList<>();try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id);ResultSet r=p.executeQuery();while(r.next()){Consultation x=new Consultation();x.id=r.getInt("id");x.userId=r.getInt("user_id");x.doctorId=r.getInt("doctor_id");x.requestedDate=r.getString("requested_date");x.mode=r.getString("mode");x.reason=r.getString("reason");x.status=r.getString("status");x.meetingLink=r.getString("meeting_link");x.doctorNotes=r.getString("doctor_notes");x.prescription=r.getString("prescription");a.add(x);}}catch(Exception e){e.printStackTrace();}return a;}public List<Consultation> byUser(int i){return f("SELECT * FROM consultations WHERE user_id=? ORDER BY requested_date DESC",i);}public List<Consultation> byDoctor(int i){return f("SELECT * FROM consultations WHERE doctor_id=? ORDER BY requested_date DESC",i);}public boolean update(int id,int d,String s,String l,String n,String pr){try(PreparedStatement p=c.prepareStatement("UPDATE consultations SET status=?,meeting_link=?,doctor_notes=?,prescription=? WHERE id=? AND doctor_id=?")){p.setString(1,s);p.setString(2,l);p.setString(3,n);p.setString(4,pr);p.setInt(5,id);p.setInt(6,d);return p.executeUpdate()==1;}catch(Exception e){return false;}}}